SELECT DISTINCTROW w.OES, w.YEAR, Sum(w.NUST) AS NUST, Sum(w.E) AS E, Sum(w.EOTP) AS EOTP, IIf([EOTP]>0,[EUST]/[EOTP]*1000,0) AS EURT, Sum(w.EUST) AS EUST, Sum(w.Q) AS Q, IIf([Q]>0,[TUST]/[Q]*1000,0) AS TURT, Sum(w.TUST) AS TUST, Sum(w.B) AS B, Sum(w.GAZ) AS GAZ, Sum(w.MAZUT) AS MAZUT, Sum(w.TORF) AS TORF, Sum(w.SLAN) AS SLAN, Sum(w.gtt) AS GTT, Sum(w.PROCH) AS PROCH, Sum(w.UGOL) AS UGOL, Sum(w.DON) AS DON, Sum(w.PODM) AS PODM, Sum(w.PECH) AS PECH, Sum(w.ARKT) AS ARKT, Sum(w.KUZN) AS KUZN, Sum(w.URAL) AS URAL, Sum(w.BASHK) AS BASHK, Sum(w.ekib) AS EKIB, Sum(w.KARAG) AS KARAG, Sum(w.KAN) AS KAN, Sum(w.IRKUT) AS IRKUT, Sum(w.HAK) AS HAK, Sum(w.TUV) AS TUV, Sum(w.BUR) AS BUR, Sum(w.CHIT) AS CHIT, Sum(w.ner) AS NER, Sum(w.raich) AS RAICH, Sum(w.URG) AS URG, Sum(w.PRIM) AS PRIM, Sum(w.LUCH) AS LUCH, Sum(w.MAG) AS MAG, Sum(w.SAH) AS SAH, Sum(IIf(w.year=1990,0,w.qotr)) AS QOTR, Sum(IIf(w.year=1990,0,w.ewtp)) AS EWTP, Sum(w.NT) AS NT, First(Имена_ОЭС.name) AS oesname, Sum(wd.nazar) AS nazar, Sum(wd.ibor) AS ibor, Sum(wd.berez) AS berez, Sum(wd.per) AS per, Sum(wd.gusin) AS gusin, Sum(wd.tugn) AS tugn, Sum(wd.azey) AS azey, Sum(wd.cher) AS cher, Sum(wd.vork) AS vork, Sum(wd.int) AS [int], Sum(wd.sver) AS sver, Sum(wd.chel) AS chel, Sum(wd.kizel) AS kizel, Sum(wd.kuzngd) AS kuzngd, Sum(wd.kuznt) AS kuznt, Sum(wd.kuznss) AS kuznss, Sum(wd.kuznun) AS kuznun, Null AS oblname, 0 AS obl, 0 AS tt, IIf([obor]=1,1,IIf([obor]=94,2,3)) AS kt
FROM (([Рабочий(станции)] AS w INNER JOIN Имена_ОЭС ON w.OES=Имена_ОЭС.oes) LEFT JOIN [Рабочий(доп_угли)] AS wd ON (w.YEAR=wd.YEAR) AND (w.NUMB1120=wd.NUMB1120)) INNER JOIN Имена_станций ON w.NUMB1120=Имена_станций.NUMB
WHERE (((w.VED)>0))
GROUP BY w.OES, w.YEAR, 0, IIf([obor]=1,1,IIf([obor]=94,2,3))
HAVING (((w.YEAR)>0));
